package org.bytefred.ktoy.core

/**
 * C compiler verification fixtures, embedded as strings (commonTest has
 * no portable filesystem access).
 *
 * For each example: the C source and the GOLDEN .toys produced by pytoy's
 * compile_source(src, name). ktoy's compileSource(src, name) must
 * reproduce the golden output byte-for-byte. The `name` is the .toyc file
 * basename (with extension), matching pytoy's scripts/build_examples.py, so
 * the "# Generated by toycc from <name>" headers agree.
 *
 * GENERATED from pytoy examples/c/ by scripts/gen_c_examples.py — do not
 * edit by hand; regenerate when the C examples or the compiler change.
 * 04-io/ examples are excluded (read/write I/O, not headless-deterministic).
 */

data class CExample(val name: String, val cSource: String, val expectedToys: String)

val C_EXAMPLES: List<CExample> = listOf(
    CExample(
        name = """bit_operators.toyc""",
        cSource = """// expect: 36
/*
 * bitops.c - showcase the bitwise operators and shifts, which map directly
 * to Toy CPU opcodes (and, or, xor, not, left, right).
 *
 *   x    = 0xF0            = 11110000
 *   y    = 0x3C            = 00111100
 *   a = x & y             = 00110000 = 0x30 = 48
 *   b = x | y             = 11111100 = 0xFC = 252
 *   c = x ^ y             = 11001100 = 0xCC = 204
 *   a = a >> 2            = 00001100 = 12
 *   a = a << 1            = 00011000 = 24
 *   result = a + (c & 0x0F)   c & 0x0F = 00001100 = 12; 24 + 12 = 36
 *
 * Expected result: ACC = 36
 */
int main(void) {
    int x = 0xF0;
    int y = 0x3C;
    int a = x & y;
    int c = x ^ y;
    a = a >> 2;
    a = a << 1;
    return a + (c & 0x0F);
}
""",
        expectedToys = """# Generated by toycc from bit_operators.toyc
# Toy CPU assembly. 8-bit values, wraps mod 256.
