        xor   v_y
        store v_c
        # a = ...
        load  c_2
        store t1
        load  v_a
        right
        right
        store v_a
        # a = ...
        load  c_1
        store t2
        load  v_a
        left
        store v_a
        # return
        load  v_c
        and   c_15
        store t3
        load  v_a
        add   t3
        stop
