        right
        right
        right
        right
        store v_msb1
        # int msb2 = ...
        load  c_0
        store v_msb2
        # if
        load  v_x
        and   c_128
        ifzero L1_if_end
        # msb2 = ...
        load  c_1
        store v_msb2
L1_if_end: nop
        # return
