        store v_a
        # int b = ...
        load  c_6
        store v_b
        # int res = ...
        load  c_0
        store v_res
        # while
L1_while_top: nop
        load  v_b
        sub   c_0
        ifzero L2_while_end
        # if
        load  v_b
        and   c_1
        ifzero L3_if_end
        # res = ...
        load  v_res
        add   v_a
        store v_res
L3_if_end: nop
        # a = ...
        load  c_1
        store t1
        load  v_a
        left
        store v_a
        # b = ...
        load  c_1
        store t2
        load  v_b
        right
        store v_b
        goto  L1_while_top
L2_while_end: nop
        # return
        load  v_res
        stop
        stop            # fallthrough halt

# data
v_a: 0
v_b: 0
v_res: 0
t1: 0
t2: 0
c_0: 0
c_1: 1
c_6: 6
c_7: 7
