/*
 * gcd_iter.c - greatest common divisor, ITERATIVE (subtraction algorithm).
 *
 * The recursive version is in gcd_rec.toyc; both compute the same result.
 *
 * gcd(48, 36): 48-36=12, 36-12=24, 24-12=12, 12-12=0 -> gcd = 12.
 *
