        # int a[10] = {...}
        # int s
        # int i
        # s = ...
        load  c_0
        store v_s
        # i = ...
        load  c_0
        store v_i
        # while
L1_while_top: nop
        load  v_i
        sub   ascii_nl_10
        and   c_128
        ifzero L2_while_end
        # s = ...
        load  v_i
        store t1
        load  arrbase_a
        add   t1
        store L3_iload_arg       # patch LOAD address to &a[idx]
        20               # LOAD opcode (raw)
L3_iload_arg: 0                # <- acc := a[idx]
        store t2
        load  v_s
        add   t2
        store v_s
        # i = ...
        load  v_i
        add   c_1
        store v_i
        goto  L1_while_top
L2_while_end: nop
        # return
        load  v_s
        stop
        stop            # fallthrough halt

# data
v_s: 0
v_i: 0
t1: 0
t2: 0
c_0: 0
c_1: 1
ascii_nl_10: 10
c_128: 128
arrbase_a: arr_a   # address of arr_a[0]
